import fs from 'node:fs';
import path from 'node:path';
import { projectDir } from './paths.js';
import { readMarkers } from './markers.js';
import { readCompositionConfig } from './composition.js';
import { syncAssetModule } from './assetModule.js';

const FULL_SCREEN_REGION = { x: 0, y: 0, width: 1, height: 1 };

// CustomOverlay.tsx and Root.tsx are deterministically generated by the runner and must
// never be edited by Claude — only the per-marker files are agent-owned.
export function regenerateRegistry(id: string): void {
  const dir = path.join(projectDir(id), '03_remotion_code');
  const markers = readMarkers(id);
  const { width: canvasWidth, height: canvasHeight } = readCompositionConfig(id);

  const imports = markers
    .map((m) => `import Marker_${m.marker_id} from './marker_${m.marker_id}';`)
    .join('\n');

  const registryEntries = markers.map((m) => `  ${m.marker_id}: Marker_${m.marker_id},`).join('\n');

  // Every marker is wrapped in a positioned, clipped div sized to its region (full screen
  // by default). This is a hard guarantee the animation can't spill outside its assigned
  // rectangle, regardless of what the marker's own generated code does — regionWidth/
  // regionHeight are passed in so that code can lay itself out relative to its actual
  // available space instead of the full canvas.
  const sequences = markers
    .map((m) => {
      const region = m.region ?? FULL_SCREEN_REGION;
      const left = Math.round(region.x * canvasWidth);
      const top = Math.round(region.y * canvasHeight);
      const width = Math.round(region.width * canvasWidth);
      const height = Math.round(region.height * canvasHeight);
      return `        <Sequence key="${m.marker_id}" from={secondsToFrames(${m.start}, fps)} durationInFrames={secondsToFrames(${m.end} - ${m.start}, fps)}>
          <div style={{ position: 'absolute', left: ${left}, top: ${top}, width: ${width}, height: ${height}, overflow: 'hidden' }}>
            <MarkerErrorBoundary markerId="${m.marker_id}">
              <Marker_${m.marker_id} regionWidth={${width}} regionHeight={${height}} />
            </MarkerErrorBoundary>
          </div>
        </Sequence>`;
    })
    .join('\n');

  const customOverlay = `// GENERATED BY THE RUNNER — do not hand-edit, do not let Claude edit this file.
import React from 'react';
import { AbsoluteFill, Sequence, useVideoConfig } from 'remotion';
import { secondsToFrames, MarkerErrorBoundary } from '@mangoai/remotion-overlay';
${imports}

export const markerRegistry = {
${registryEntries}
};

export default function CustomOverlay() {
  const { fps } = useVideoConfig();
  return (
    <AbsoluteFill>
${sequences}
    </AbsoluteFill>
  );
}
`;

  fs.writeFileSync(path.join(dir, 'CustomOverlay.tsx'), customOverlay);

  const root = `// GENERATED BY THE RUNNER — used only by \`npx remotion render\` for final export.
import React from 'react';
import { Composition, registerRoot } from 'remotion';
import CustomOverlay from './CustomOverlay';
import config from './CompositionConfig.json';

const Root: React.FC = () => (
  <Composition
    id="Overlay"
    component={CustomOverlay}
    durationInFrames={config.durationInFrames}
    fps={config.fps}
    width={config.width}
    height={config.height}
  />
);

registerRoot(Root);
`;

  fs.writeFileSync(path.join(dir, 'Root.tsx'), root);
  syncAssetModule(id);
}
